// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz the caller address who will be the owner (must be the deploying address in setUp),
    // so instead fuzz a dummy nonzero address to ensure we exercise owner mechanics by calling as owner.
    // We fuzz an arbitrary address 'actor' but we will only use it with vm.prank when it equals the actual owner.
    function testFuzz_property(address actor) public {
        // Ensure actor is non-zero to be a valid EOA and not the zero address
        vm.assume(actor != address(0));

        // The contract's constructor set owner = msg.sender where c was deployed by this test contract.
        // In order to call NETM as owner, we must act as the test contract (address(this) in EVM is a special address),
        // but Foundry's vm.prank can impersonate an EOA. The actual owner is the test contract's address that deployed c,
        // which is address(this). So we prank as address(this) to call NETM.

        // Before calling NETM, read totalDistributed and owner's balance
        uint256 totalDist = c.totalDistributed();
        address ownerBefore = address(this); // deployer of c in setUp
        uint256 balBefore = c.balanceOf(ownerBefore);

        // Sanity: in reference contract constructor NETM was not called; but setUp used new C(), which sets owner=msg.sender
        // and balances[owner] should initially equal totalDistributed only after NETM is called. We now call NETM as owner.

        bool ok;
        // Call NETM as owner (the test contract) and catch reverts
        try c.NETM{gas: gasleft()}() {
            ok = true;
        } catch {
            ok = false;
        }

        // After the call, the reference implementation sets owner = msg.sender (owner remains same) and
        // sets balances[owner] == totalDistributed. Thus for the reference contract, if the call succeeded,
        // balances[ownerBefore] == totalDistributed must hold. The mutant that assigns owner = address(0)
        // will set balances[address(0)] = totalDistributed, leaving balances[ownerBefore] unchanged, so this
        // assertion will fail for some inputs (specifically when caller is owner and call succeeds).

        // We assert the universal property: if NETM call succeeded, then balances[ownerBefore] == totalDistributed.
        // This holds for the reference for all inputs; the mutant violates it for at least some input.
        if (ok) {
            assertTrue(c.balanceOf(ownerBefore) == c.totalDistributed());
        } else {
            // If the call reverted, still assert that the revert behavior is consistent (we do not require success).
            // To keep a single assertion per requirement, we assertTrue on a trivially true condition when ok==false.
            // However the mandated single assertion must observe c; so we check that balance did not become totalDistributed
            // when call reverted (balance stays as before). This still reads c.
            assertTrue(c.balanceOf(ownerBefore) == balBefore);
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed param: an address that will become the owner via NETM
    function testFuzz_property(address newOwner) public {
        // keep address non-zero to be meaningful
        vm.assume(newOwner != address(0));

        // ensure caller is the current owner (constructor set owner = msg.sender in C, which is this test contract)
        // NETM is onlyOwner, so we must call as current owner. The test contract is the owner because it deployed c in setUp().

        // call NETM as the owner but with msg.sender set to this test contract (already true)
        // The NETM function sets owner = msg.sender (keeps owner as this test contract) in both versions,
        // but in the reference it also credits balances[owner] = totalDistributed. To transfer ownership to newOwner,
        // we use transferOwnership afterwards to set the owner to newOwner to observe balances at that address.

        // First, call NETM() (this is onlyOwner, allowed since this test contract deployed c)
        bool ok;
        try c.NETM() {
            ok = true;
        } catch {
            ok = false;
        }
        // NETM should not revert on the reference; still, we don't assert on ok because both versions execute NETM.

        // Now transfer ownership to a chosen address so that we can check balances[newOwner]
        // transferOwnership requires onlyOwner, so call it as current owner (this test contract)
        c.transferOwnership(newOwner);

        // The invariant we assert: in the reference, the owner's balance equals totalDistributed.
        // We read balances via the public getter balanceOf(newOwner), and totalDistributed via public variable.
        uint256 ownerBalance = c.balanceOf(newOwner);
        uint256 totalDistributed = c.totalDistributed();

        // Single assertion: reference satisfies balances[owner] == totalDistributed for any newOwner;
        // the mutant that omits crediting balances will fail for at least some newOwner (specifically the owner that should have been credited).
        assertTrue(ownerBalance == totalDistributed);
    }
}

