pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the caller address that will call NETM(); it must be the owner to pass onlyOwner
    function testFuzz_property(address caller) public {
        // restrict to non-zero address (owner cannot be zero in meaningful scenario)
        vm.assume(caller != address(0));

        // ensure the caller is the current owner so call will succeed
        // the contract sets owner = msg.sender in its constructor to address(this) from new C();
        // we need to transfer ownership to `caller` so that caller is owner when calling NETM.
        // Only current owner can call transferOwnership; current owner is address(this) from constructor,
        // but in test we are external EOA, so we first call transferOwnership as the test (which is allowed
        // because setUp deployed c from this test contract address). The test contract is the owner.

        // transfer ownership to the fuzzed caller
        c.transferOwnership(caller);

        // now have the fuzzed caller invoke NETM() — NETM is onlyOwner so must be called by caller.
        vm.prank(caller);
        // call NETM(); if it reverts (shouldn't in reference when caller is owner), catch via try/catch would be used,
        // but here we expect it to succeed; nevertheless we just invoke it.
        c.NETM();

        // Single assertion: in the correct contract NETM assigns owner and credits balances[owner] == totalDistributed;
        // read owner via public getter: owner is not declared public, but the change of balances happens to the caller's
        // balances slot — however per constraints we may only observe through public surface. totalDistributed is public.
        // The contract does not expose owner as public; to observe the property that the reference guarantees for ALL inputs
        // we instead check that there exists some address whose balance equals totalDistributed AND that the caller's balance equals totalDistributed.
        // But we must use a single assertTrue reading c's public surface. The contract exposes balanceOf and totalDistributed.

        // The intended distinguishing fact: after NETM() is called by owner, in reference balances[caller] == totalDistributed; mutant leaves it 0.
        // So we assert that balanceOf(caller) == totalDistributed()
        uint256 bal = c.balanceOf(caller);
        uint256 td = c.totalDistributed();
        assertTrue(bal == td);
    }
}

