pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz the caller address to become the new owner; we must ensure caller is owner in order to call NETM()
    // so we will first transfer ownership to the fuzzed address by calling transferOwnership from the initial owner
    // The general property: after NETM() is called by the owner, balances[owner] == totalDistributed.
    function testFuzz_property(address newOwner) public {
        // keep newOwner within normal address space (exclude zero to be meaningful)
        vm.assume(newOwner != address(0));

        // initial owner is the deployer, which is the test contract's address when creating C via new C()
        // However in this setup owner was set to msg.sender at construction (setUp called from this contract), so
        // the test contract is the owner. We need to make newOwner the caller of NETM(), so transfer ownership.

        // transfer ownership to newOwner
        c.transferOwnership(newOwner);

        // now call NETM() as newOwner
        vm.prank(newOwner);
        // Use try/catch to capture possible revert but NETM is onlyOwner, so should succeed
        bool ok;
        try c.NETM() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property for the reference: after NETM by the owner, balances[owner] == totalDistributed
        // We observe via public getters: c.owner() does not exist (owner is private), but NETM sets owner = msg.sender
        // and there is no getter for owner; however the behavior we can read is balances[newOwner] equals totalDistributed.
        // totalDistributed is public, and balanceOf is public.

        uint256 td = c.totalDistributed();
        uint256 bal = c.balanceOf(newOwner);

        // Single assertion: in the correct contract, calling NETM() as owner results in balances[newOwner] == totalDistributed.
        // The mutant that assigns balances to the previous owner will make this assertion fail for some newOwner.
        assertTrue(ok && bal == td);
    }
}

