pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz the caller who will be the owner when calling NETM
    function testFuzz_property(address newOwner) public {
        // keep newOwner non-zero to be a sensible owner candidate
        vm.assume(newOwner != address(0));

        // The contract's constructor set owner = msg.sender (the test contract),
        // but NETM is protected by onlyOwner. To test the behavior when an
        // arbitrary address becomes owner and then calls NETM, we first
        // transfer ownership to newOwner by calling transferOwnership from the
        // current owner (this contract). That models the general situation
        // where some owner calls NETM.

        // ensure this contract is the current owner (it is, as setUp used new C())
        // now transfer ownership to newOwner
        c.transferOwnership(newOwner);

        // Now impersonate newOwner and call NETM(). NETM() in reference sets
        // owner = msg.sender and balances[owner] = totalDistributed (in that
        // order). The invariant we assert: after NETM, balances[ owner() ] == totalDistributed.
        vm.prank(newOwner);
        c.NETM();

        // single assertion: reference must always hold this; mutant (which
        // writes balances[oldOwner] = totalDistributed before updating owner)
        // will fail for some newOwner choices (specifically any newOwner != test contract),
        // so the fuzzer can find a counterexample.
        assertTrue(c.balanceOf(c.owner()) == c.totalDistributed());
    }
}
